list_shipping_classes.code:
var response = await client.ShippingClasses.ListShippingClassesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var shippingClass in ((IReadOnlyList<object?>)body["shipping_classes"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{shippingClass["id"]} {shippingClass["name"]} {shippingClass["is_default"]}");

